  if (e?.scope === "user" || e?.scope === "site") err.scope = e.scope;
  if (typeof e?.resets_at === "string") err.resetsAt = e.resets_at;
  return err;
}

async function req<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`/api${path}`, {
    ...init,
